import { createHash } from "node:crypto";
import { describe, expect, it, vi } from "vitest";
import {
  trackAgentCreated,
  trackAgentFirstHeartbeat,
  trackAgentTaskCompleted,
  trackAgentTaskRun,
  trackInteractionCreated,
  trackInteractionResolved,
  trackInstallCompleted,
} from "@paperclipai/shared/telemetry";
import type { EventDimensionsMap, TelemetryClient } from "@paperclipai/shared/telemetry";

function createClient(): TelemetryClient {
  return {
    track: vi.fn(),
    hashPrivateRef: vi.fn((value: string) => createHash("sha256").update(value).digest("hex").slice(0, 16)),
  } as unknown as TelemetryClient;
}

function runtimeValue<T>(value: string): T {
  return value as T;
}

describe("shared telemetry agent events", () => {
  it("includes agent_id for agent.created", () => {
    const client = createClient();

    trackAgentCreated(client, {
      agentRole: "engineer",
      agentId: "11111111-1111-4111-8111-111111111111",
    });

    expect(client.track).toHaveBeenCalledWith("agent.created", {
      agent_role: "engineer",
      agent_id: "11111111-1111-4111-8111-111111111111",
    });
  });

  it("passes an unrecognized agent role through for backend normalization", () => {
    const client = createClient();

    trackAgentCreated(client, {
      agentRole: runtimeValue<EventDimensionsMap["agent.created"]["agent_role"]>("coder"),
      agentId: "44444444-4444-4444-8444-444444444444",
    });

    expect(client.track).toHaveBeenCalledWith("agent.created", {
      agent_role: "coder",
      agent_id: "44444444-4444-4444-8444-444444444444",
    });
  });

  it("includes agent_id for agent.first_heartbeat", () => {
    const client = createClient();

    trackAgentFirstHeartbeat(client, {
      agentRole: "engineer",
      agentId: "22222222-2222-4222-8222-222222222222",
    });

    expect(client.track).toHaveBeenCalledWith("agent.first_heartbeat", {
      agent_role: "engineer",
      agent_id: "22222222-2222-4222-8222-222222222222",
    });
  });

  it("includes agent_id for agent.task_completed", () => {
    const client = createClient();

    trackAgentTaskCompleted(client, {
      agentRole: "qa",
      agentId: "33333333-3333-4333-8333-333333333333",
      adapterType: "codex_local",
    });

    expect(client.track).toHaveBeenCalledWith("agent.task_completed", {
      agent_role: "qa",
      agent_id: "33333333-3333-4333-8333-333333333333",
      adapter_type: "codex_local",
    });
  });

  it("hashes the task id for agent.task_completed and never sends the raw value", () => {
    const client = createClient();
    const rawTaskId = "11111111-1111-4111-8111-111111111111";

    trackAgentTaskCompleted(client, {
      agentRole: "qa",
      agentId: "33333333-3333-4333-8333-333333333333",
      adapterType: "codex_local",
      taskId: rawTaskId,
    });

    expect(client.hashPrivateRef).toHaveBeenCalledWith(rawTaskId);
    const sentDimensions = vi.mocked(client.track).mock.calls[0]?.[1] as Record<string, unknown>;
    expect(sentDimensions.task_id).toMatch(/^[0-9a-f]{16}$/);
    expect(sentDimensions.task_id).not.toBe(rawTaskId);
    expect(JSON.stringify(sentDimensions)).not.toContain(rawTaskId);
  });

  it("omits task_id for agent.task_completed when the caller gives no task id", () => {
    const client = createClient();

    trackAgentTaskCompleted(client, {
      agentRole: "qa",
      agentId: "33333333-3333-4333-8333-333333333333",
      adapterType: "codex_local",
    });

    expect(client.hashPrivateRef).not.toHaveBeenCalled();
    expect(client.track).toHaveBeenCalledWith("agent.task_completed", {
      agent_role: "qa",
      agent_id: "33333333-3333-4333-8333-333333333333",
      adapter_type: "codex_local",
    });
  });

  it("sends all ten dimensions for agent.task_run when present", () => {
    const client = createClient();
    const rawTaskId = "22222222-2222-4222-8222-222222222222";

    trackAgentTaskRun(client, {
      agentId: "44444444-4444-4444-8444-444444444444",
      state: "succeeded",
      adapterType: "claude_local",
      agentRole: "engineer",
      model: "claude-sonnet-5",
      durationSeconds: 12.5,
      inputTokens: 100,
      outputTokens: 200,
      cachedTokens: 50,
      taskId: rawTaskId,
    });

    expect(client.hashPrivateRef).toHaveBeenCalledWith(rawTaskId);
    const sentDimensions = vi.mocked(client.track).mock.calls[0]?.[1] as Record<string, unknown>;
    expect(sentDimensions).toMatchObject({
      agent_id: "44444444-4444-4444-8444-444444444444",
      state: "succeeded",
      adapter_type: "claude_local",
      agent_role: "engineer",
      model: "claude-sonnet-5",
      duration_seconds: 12.5,
      input_tokens: 100,
      output_tokens: 200,
      cached_tokens: 50,
    });
    expect(sentDimensions.task_id).toMatch(/^[0-9a-f]{16}$/);
  });

  it("omits every absent optional dimension for agent.task_run", () => {
    const client = createClient();

    trackAgentTaskRun(client, {
      agentId: "55555555-5555-4555-8555-555555555555",
      state: "failed",
    });

    expect(client.hashPrivateRef).not.toHaveBeenCalled();
    expect(client.track).toHaveBeenCalledWith("agent.task_run", {
      agent_id: "55555555-5555-4555-8555-555555555555",
      state: "failed",
    });
  });

  it("keeps non-agent event dimensions unchanged", () => {
    const client = createClient();

    trackInstallCompleted(client, { adapterType: "codex_local" });

    expect(client.track).toHaveBeenCalledWith("install.completed", {
      adapter_type: "codex_local",
    });
    expect(client.track).not.toHaveBeenCalledWith(
      "install.completed",
      expect.objectContaining({ agent_id: expect.any(String) }),
    );
  });

  it("passes interaction.resolved enum dimensions through for backend normalization", () => {
    const client = createClient();

    trackInteractionResolved(client, {
      interactionKind: runtimeValue<EventDimensionsMap["interaction.resolved"]["interaction_kind"]>(
        "single_confirmation",
      ),
      status: "accepted",
      resolvedByKind: runtimeValue<EventDimensionsMap["interaction.resolved"]["resolved_by_kind"]>("operator"),
      resolutionReason: "accepted",
      createdByKind: "agent",
      creatorAgentRole: runtimeValue<EventDimensionsMap["interaction.resolved"]["creator_agent_role"]>("coder"),
      continuationPolicy: runtimeValue<EventDimensionsMap["interaction.resolved"]["continuation_policy"]>(
        "wake_everyone",
      ),
      targetType: "issue_document",
      optionCount: 2,
      selectedOptionCount: 1,
      skippedTaskCount: 3,
      legacyInheritedRestriction: true,
    });

    expect(client.track).toHaveBeenCalledWith("interaction.resolved", {
      interaction_kind: "single_confirmation",
      status: "accepted",
      resolved_by_kind: "operator",
      resolution_reason: "accepted",
      created_by_kind: "agent",
      creator_agent_role: "coder",
      continuation_policy: "wake_everyone",
      target_type: "issue_document",
      option_count: 2,
      selected_option_count: 1,
      skipped_task_count: 3,
      legacy_inherited_restriction: true,
    });
  });

  it("emits only enum and boolean dimensions for interaction creation compatibility", () => {
    const client = createClient();

    trackInteractionCreated(client, {
      interactionKind: "request_confirmation",
      usedDeprecatedResolverPolicyAlias: true,
    });

    expect(client.track).toHaveBeenCalledWith("interaction.created", {
      interaction_kind: "request_confirmation",
      used_deprecated_resolver_policy_alias: true,
    });
  });
});

package event

import (
	"reasonix/internal/evidence"
	"reasonix/internal/nilutil"
)

// AuditForwarder forwards every optional sink capability to Inner. Embed it in
// a wrapper that only passes host-side signals through, so a channel added here
// reaches every embedder without editing them. Hand-written forwarding lost
// capabilities at multiple wrappers even while their owning tests stayed green.
type AuditForwarder struct{ Inner Sink }

// OptionalSinkCapabilities is the complete host-side capability contract that
// event decorators must preserve. Keeping the method set in one interface lets
// wrappers use compile-time assertions instead of maintaining partial lists in
// tests that silently drift when a new capability is added.
type OptionalSinkCapabilities interface {
	RuntimeStateSink
	DelegationAuditSink
	ReadinessAuditSink
	AnchorSafetyAuditSink
	ContractShadowAuditSink
	CompletionReportAuditSink
	MemoryRecallSink
	DelegationAdmissionSink
	OutcomeProgressSink
	ProtocolRecoveryAuditSink
	TurnCompletionSink
	WorkspaceMutationSink
	RunBudgetSink
	SubagentLifecycleAuditSink
}

var _ OptionalSinkCapabilities = AuditForwarder{}

func (f AuditForwarder) RecordReadinessAudit(a evidence.ReadinessAudit) {
	RecordReadinessAudit(f.Inner, a)
}

func (f AuditForwarder) RecordAnchorSafetyAudit(a AnchorSafetyAudit) {
	RecordAnchorSafetyAudit(f.Inner, a)
}

func (f AuditForwarder) RecordTurnCompletion() { RecordTurnCompletion(f.Inner) }

func (f AuditForwarder) RecordContractShadow(a ContractShadowAudit) {
	RecordContractShadow(f.Inner, a)
}

func (f AuditForwarder) RecordCompletionReport(a CompletionReportAudit) {
	RecordCompletionReport(f.Inner, a)
}

func (f AuditForwarder) RecordMemoryRecall(a MemoryRecallAudit) {
	RecordMemoryRecall(f.Inner, a)
}

func (f AuditForwarder) RecordDelegationAdmission(a DelegationAdmissionAudit) {
	RecordDelegationAdmission(f.Inner, a)
}

func (f AuditForwarder) RecordOutcomeProgress(s evidence.OutcomeSample) {
	RecordOutcomeProgress(f.Inner, s)
}

func (f AuditForwarder) RecordProtocolRecovery(a ProtocolRecoveryAudit) {
	RecordProtocolRecovery(f.Inner, a)
}

func (f AuditForwarder) RecordDelegationAudit(a evidence.DelegationAudit) {
	RecordDelegationAudit(f.Inner, a)
}

func (f AuditForwarder) RecordWorkspaceMutation(m WorkspaceMutation) {
	RecordWorkspaceMutation(f.Inner, m)
}

func (f AuditForwarder) RecordRunBudget(s RunBudgetSample) {
	RecordRunBudget(f.Inner, s)
}

func (f AuditForwarder) RecordSubagentLifecycle(info SubagentLifecycleInfo) {
	RecordSubagentLifecycle(f.Inner, info)
}

// DelegationAuditSink receives one receipt per completed sub-agent run.
type DelegationAuditSink interface {
	RecordDelegationAudit(a evidence.DelegationAudit)
}

// RecordDelegationAudit forwards a delegation receipt to sinks that opt in.
func RecordDelegationAudit(s Sink, a evidence.DelegationAudit) {
	if nilutil.IsNil(s) {
		return
	}
	if ds, ok := s.(DelegationAuditSink); ok {
		ds.RecordDelegationAudit(a)
	}
}

